#include <stdio.h>
int n; int colOf[20], usedC[20], d1[64], d2[64];
char out[4000000]; int op=0, first=1;
void emit(){ if(!first) out[op++]=','; first=0; out[op++]='[';
  for(int i=0;i<n;i++){ if(i)out[op++]=','; out[op++]='"'; for(int j=0;j<n;j++) out[op++]=(colOf[i]==j)?'Q':'.'; out[op++]='"'; } out[op++]=']'; }
void solve(int r){ if(r==n){ emit(); return; }
  for(int c=0;c<n;c++){ if(usedC[c]||d1[r+c]||d2[r-c+20]) continue;
    usedC[c]=d1[r+c]=d2[r-c+20]=1; colOf[r]=c; solve(r+1); usedC[c]=d1[r+c]=d2[r-c+20]=0; } }
int main(){ scanf("%d",&n); out[op++]='['; solve(0); out[op++]=']'; out[op]=0; printf("%s\n",out); return 0; }

