N-Queens.java:
import java.util.*;
public class Main{
  static int n; static int[] colOf=new int[20]; static boolean[] usedC=new boolean[20], d1=new boolean[64], d2=new boolean[64];
  static StringBuilder out=new StringBuilder(); static boolean first=true;
  static void emit(){ if(!first) out.append(','); first=false; out.append('[');
    for(int i=0;i<n;i++){ if(i>0)out.append(','); out.append('"'); for(int j=0;j<n;j++) out.append(colOf[i]==j?'Q':'.'); out.append('"'); } out.append(']'); }
  static void solve(int r){ if(r==n){ emit(); return; }
    for(int c=0;c<n;c++){ if(usedC[c]||d1[r+c]||d2[r-c+20]) continue;
      usedC[c]=d1[r+c]=d2[r-c+20]=true; colOf[r]=c; solve(r+1); usedC[c]=d1[r+c]=d2[r-c+20]=false; } }
  public static void main(String[] z){ Scanner s=new Scanner(System.in); n=s.nextInt(); out.append('['); solve(0); out.append(']'); System.out.println(out.toString()); }
}
